[Fact]
public async Task TrainBatch_IgnoresPromptUsefulnessScoreWhenPersistingLearnedWeights()
{
    var machine = new DesignConversionMachine();

    var train = await machine.TrainBatchAsync(BuildPass150Batch("gc2-usefulness-score-not-learned", 0.95, 0.15));

    Assert.True(train.IsSuccess, train.ErrorMessage);
    var checkpoint = machine.ExportCheckpoint();
    Assert.True(checkpoint.IsSuccess, checkpoint.ErrorMessage);
    var criticWeights = checkpoint.Value!.CriticUnit.LearnedWeights ?? [];
    Assert.Contains(criticWeights, weight => string.Equals("source_manifest:hash_diversity", weight.FeatureKey, StringComparison.Ordinal));
    Assert.DoesNotContain(
        criticWeights,
        weight => weight.FeatureKey.Contains("usefulness", StringComparison.OrdinalIgnoreCase) ||
                  weight.FeatureKey.Contains("review_priority", StringComparison.OrdinalIgnoreCase) ||
                  weight.FeatureKey.Contains("accepted_delta", StringComparison.OrdinalIgnoreCase) ||
                  weight.FeatureKey.Contains("score_margin", StringComparison.OrdinalIgnoreCase) ||
                  string.Equals("visual:chosen_score", weight.FeatureKey, StringComparison.Ordinal) ||
                  string.Equals("visual:rejected_score_inverse", weight.FeatureKey, StringComparison.Ordinal) ||
                  weight.Derivation.Contains("usefulness", StringComparison.OrdinalIgnoreCase));

private static OperationResult<Dictionary<string, Dictionary<string, LearnedWeightAccumulator>>> BuildLearnedWeightImport(
    DesignConversionMachineCheckpoint checkpoint)
{
    var stagedWeights = new Dictionary<string, Dictionary<string, LearnedWeightAccumulator>>(StringComparer.Ordinal);
    var critic = StageLearnedWeights(checkpoint.CriticUnit, stagedWeights);
    if (!critic.IsSuccess)
        return critic.MapError<Dictionary<string, Dictionary<string, LearnedWeightAccumulator>>>();

    var improver = StageLearnedWeights(checkpoint.ImproverUnit, stagedWeights);
    if (!improver.IsSuccess)
        return improver.MapError<Dictionary<string, Dictionary<string, LearnedWeightAccumulator>>>();

    return OperationResult<Dictionary<string, Dictionary<string, LearnedWeightAccumulator>>>.Ok(stagedWeights);
}

private static OperationResult<bool> StageLearnedWeights(
    DesignConversionRuntimeUnitCheckpoint unit,
    Dictionary<string, Dictionary<string, LearnedWeightAccumulator>> stagedWeights)
{
    var weights = unit.LearnedWeights ?? [];
    if (!unit.LearnedWeightsPresent && weights.Count > 0)
    {
        return OperationResult<bool>.Fail(
            $"Checkpoint unit '{unit.UnitId}' contains learned weights but LearnedWeightsPresent is false.",
            "CHECKPOINT_LEARNED_WEIGHTS_INVALID");
    }

    if (unit.LearnedWeightsPresent &&
        (weights.Count == 0 ||
         weights.Any(weight => !IsValidLearnedWeight(weight)) ||
         HasDuplicateLearnedWeightFeatureKeys(weights)))
    {
        return OperationResult<bool>.Fail(
            $"Checkpoint unit '{unit.UnitId}' claims learned weights without a valid persisted artifact.",
            "CHECKPOINT_LEARNED_WEIGHTS_INVALID");
    }

    if (weights.Count == 0)
        return OperationResult<bool>.Ok(true);

    var byFeature = GetUnitAccumulatorMap(stagedWeights, unit.UnitId);
    foreach (var weight in weights)
    {
        byFeature[weight.FeatureKey] = LearnedWeightAccumulator.FromCheckpoint(weight);
    }

    return OperationResult<bool>.Ok(true);

internal static DesignConversionDpoNormalizedSourceSignal Normalize(
    DesignConversionDpoTrainingRecord row)
{
    ArgumentNullException.ThrowIfNull(row);
    var metadata = row.Provenance.Metadata ?? new Dictionary<string, string>();
    var encoderName = SanitizeScalar(ReadMetadata(metadata, "source_encoder"), 96);
    var encoderSchema = SanitizeScalar(ReadMetadata(metadata, "source_encoder_schema"), 64);
    var encoderRole = SanitizeScalar(ReadMetadata(metadata, "source_encoder_role"), 128);
    var encoderAuthority = SanitizeScalar(ReadMetadata(metadata, "source_encoder_authority"), 128);
    var featureNamespace = SanitizeScalar(ReadMetadata(metadata, "source_encoder_feature_namespace"), 96);
    var featureNames = SanitizeScalar(ReadMetadata(metadata, "source_encoder_feature_names"), 384);
    var structureSummary = SanitizeScalar(ReadMetadata(metadata, "source_structure_signal_summary"), 192);
    var vectorHash = SanitizeScalar(ReadMetadata(metadata, "source_encoder_vector_hash"), 96);
    var featureMapHash = SanitizeScalar(ReadMetadata(metadata, "source_encoder_feature_map_hash"), 96);
    var shortcutGuard = SanitizeScalar(ReadMetadata(metadata, "source_encoder_shortcut_guard"), 96);
    var vectorPrefix = BuildVectorPrefix(row.InternalVectorPayload);
    var vectorPayloadHash = HashVectorPayload(row.InternalVectorPayload);
    var policyPromptText = string.Join(
        " ",
        "srcenc",
        $"vecp={string.Join(",", vectorPrefix.Select(value => value.ToString("0.###", CultureInfo.InvariantCulture)))}",
        $"schema={encoderSchema}",
        $"sig={structureSummary}",
        $"fmap={featureMapHash}",
        $"vecn={row.InternalVectorPayload.Count.ToString(CultureInfo.InvariantCulture)}",
        $"guard={shortcutGuard}");

    return new DesignConversionDpoNormalizedSourceSignal(
        encoderName,
        encoderSchema,
        encoderRole,
        encoderAuthority,
        featureNamespace,
        featureNames,
        structureSummary,
        vectorHash,
        featureMapHash,
        shortcutGuard,
        row.InternalVectorPayload.Count,
        vectorPrefix,
        vectorPayloadHash,
        policyPromptText);
}

internal static string BuildPolicyPrompt(DesignConversionDpoTrainingRecord row)
{
    var signal = Normalize(row);
    return string.Join(
        " ",
        signal.PolicyPromptText,
        $"unit={SanitizeScalar(NormalizeUnitId(row.UnitId), 64)}");
}

